MultiLanguageSpellData['de'][66] = {name = "Unsichtbarkeit", additional_info = "3% von Grundmana\nSofort 5 min Abklingzeit\n[q]Lässt Euch im Verlauf von 3 Sek. bis zur Unsichtbarkeit verblassen und verringert mit jeder Sekunde die Bedrohung. Während Ihr unsichtbar seid, könnt Ihr von Gegnern nicht als Ziel gewählt werden. Hält 20 Sek. lang an. Wenn Ihr Aktionen ausführt, wird der Effekt abgebrochen."}
MultiLanguageSpellData['de'][71] = {name = "Frontkämpfer", additional_info = "[q]Ihr seid vom Kampf gestählt, was Eure Ausdauer um 40% erhöht und Eure Rüstung um 70% Eurer Stärke erhöht.\n(500ms Abklingzeit)"}
