MultiLanguageSpellData['de'][99] = {name = "Erschütterndes Gebrüll", additional_info = "{Sofort} {30 sek. Abklingzeit}\n[q]Verwandelt Euch in Bärengestalt und ruft den Geist Ursols an, um ein ohrenbetäubendes Gebrüll auszustoßen, das alle Gegner innerhalb von 10 Metern 3 Sek. lang handlungsunfähig macht. Schaden kann den Effekt beenden."}
MultiLanguageSpellData['de'][100] = {name = "Sturmangriff", additional_info = "8 - 25 Meter Reichweite\n{Sofort} {20 sek. Abklingzeit}\n1 Aufladung\n[q]Stürmt auf einen Gegner zu, verursacht (21% of Attack power) körperlichen Schaden und macht ihn für 1 Sek. bewegungsunfähig. [ Kriegstreiber : Zusätzlich wird er für bis Abbruch betäubt ]\nErzeugt 20 Wut."}
MultiLanguageSpellData['de'][101] = {name = "Straucheln", additional_info = "{15 Energie} {Nahkampfreichweite}\n{Sofort} {5 sek. Abklingzeit}\n[q]Bringt den humanoiden Feind zu Fall, wobei 6 Schaden verursacht werden und der Gegner 3 Sek. lang am Boden liegt. Gewährt 1 Combopunkt."}
MultiLanguageSpellData['de'][107] = {name = "Blocken", additional_info = "Benötigt Schild\n[q]Gewährt die Chance, Nahkampfattacken und Distanzangriffe des Feindes zu blocken."}
