MultiLanguageSpellData['de'][113] = {name = "Eisketten", additional_info = "30 Meter Reichweite\nWirken in 1.5 sek.\n[q]Schlingt eisige Ketten um das Ziel, welche es 6 Sek. lang an Ort und Stelle festhalten."}
MultiLanguageSpellData['de'][116] = {name = "Frostblitz", additional_info = "{2% von Grundmana} {40 Meter Reichweite}\nWirken in 2 sek.\n[q]Schleudert einen Frostblitz auf den Gegner, der (106.37% of Spell power) Frostschaden verursacht und seine Bewegungsgeschwindigkeit 8 Sek. lang um 50% verringert."}
MultiLanguageSpellData['de'][118] = {name = "Verwandlung", additional_info = "{4% von Grundmana} {30 Meter Reichweite}\nWirken in 1.7 sek.\n[q]Verwandelt den Gegner in ein Schaf, das 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden kann den Effekt abbrechen. Es kann nur jeweils 1 Ziel betroffen sein.\n\n Wirkt nur bei Wildtieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]"}
MultiLanguageSpellData['de'][120] = {name = "Kältekegel", additional_info = "4% von Grundmana\n{Sofort} {12 sek. Abklingzeit}\n[q]Ziele in einem kegelförmigen Bereich vor Euch erleiden (43.125% of Spell power) Frostschaden und ihre Bewegungsgeschwindigkeit ist 5 Sek. lang um 70% verringert ."}
MultiLanguageSpellData['de'][122] = {name = "Frostnova", additional_info = "2% von Grundmana\n{Sofort} {30 sek. Abklingzeit}\n1 Aufladung\n[q]Fügt Gegnern innerhalb von 12 Metern um Euch (5.149% of Spell power) Frostschaden zu und friert sie 6 Sek. lang fest. Schaden kann den Bewegungsunfähigkeitseffekt unterbrechen."}
MultiLanguageSpellData['de'][126] = {name = "Auge von Kilrogg", additional_info = "3% von Grundmana Unbegrenzte Reichweite\nWirken in 2 sek.\n[q]Beschwört ein Auge von Kilrogg und bindet Eure Sicht daran. Das Auge ist getarnt und bewegt sich schnell, ist sehr sehr verwundbar."}
MultiLanguageSpellData['de'][130] = {name = "Langsamer Fall", additional_info = "{1% von Grundmana} {40 Meter Reichweite}\nSofort\n[q]Verringert 30 Sek. lang die Fallgeschwindigkeit eines Gruppenmitglieds."}
MultiLanguageSpellData['de'][133] = {name = "Feuerball", additional_info = "{1% von Grundmana} {40 Meter Reichweite}\nWirken in 2.25 sek.\n[q]Wirft eine feurige Kugel, die (154.8% of Spell power) Feuerschaden verursacht."}
MultiLanguageSpellData['de'][134] = {name = "Feuerschild", additional_info = "30 Meter Reichweite\n{Wirken in} {1 sek. 15 sek. Abklingzeit}\n[q]Umgibt einen Verbündeten mit einem Flammenschild, der alle 3 Sek. in der Nähe befindlichen Feinden 1 Feuerschaden zufügt. Hält 1 Min. lang an."}
MultiLanguageSpellData['de'][136] = {name = "Tier heilen", additional_info = "45 Meter Reichweite\n{Sofort} {10 sek. Abklingzeit}\n[q]Heilt Euren Begleiter im Verlauf von 10 Sek. um 50% seiner gesamten Gesundheit. [ Medizin der Wildnis : Pro Tick besteht eine Chance von 25%, einen schädlichen Magieeffekt von Eurem Begleiter zu entfernen ]"}
