MultiLanguageSpellData['de'][370] = {name = "Reinigen", additional_info = "{14% von Grundmana} {30 Meter Reichweite}\nSofort\n[q]Reinigt das gegnerische Ziel und entzieht 1 nützlichen magischen Effekt.\n [Ist 'Reinigen' erfolgreich, wird Euch eine Aufladung von 'Waffe des Mahlstroms' gewährt.]"}
MultiLanguageSpellData['de'][379] = {name = "Erdschild", additional_info = "300 Meter Reichweite\nSofort\n[q]Schützt das Ziel mit einem Erdschild, der Eure bei diesem Ziel hervorgerufene Heilung um 20% erhöht und es bei erlittenem Schaden um [(73% of Spell power) * 1.2] Gesundheit heilt. Diese Heilung kann nur einmal alle 3 Sek. auftreten. Maximal 9 Aufladungen .\n\n [ Elementare Umkreisung : 'Erdschild' kann immer nur auf den Schamanen und ein weiteres Ziel gleichzeitig angewendet werden. Es können bis zu zwei Elementarschilde auf dem Schamanen aktiv sein / 'Erdschild' kann immer nur auf ein Ziel gleichzeitig angewendet werden. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.]"}
MultiLanguageSpellData['de'][408] = {name = "Nierenhieb", additional_info = "{25 Energie} {/ 1 zu 5 Combopunkte Nahkampfreichweite}\n{Sofort} {30 sek. Abklingzeit}\nBenötigt Nahkampfwaffe\n[q]Finishing-Move, der das Ziel betäubt . Hält pro Combopunkt länger an, bis zu maximal 8 Sek.:\n 1 Punkt: 4 Sek.\n 2 Punkte: 5 Sek.\n 3 Punkte: 6 Sek.\n 4 Punkte: 7 Sek.\n 5 Punkte: 8 Sek."}
