MultiLanguageSpellData['de'][467] = {name = "Dornen", additional_info = "{36% von Grundmana} {30 Meter Reichweite}\n{Sofort} {45 sek. Abklingzeit}\n[q]Thorns sprout from the friendly target causing [(0 + (Spell power * .168)) * 1] Nature damage to attackers when hit. Lasts 20 Sek.."}
