MultiLanguageSpellData['de'][578] = {name = "Schwarzer Wolf", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren schwarzen Wolf oder gibt ihn wieder frei.\n[q]\"Heult laut genug, um meilenweit gehört zu werden.\"\nVerkäufer:\nOgunaro Wolfsläufer\nZone:\nOrgrimmar\nKosten:\n1"}
MultiLanguageSpellData['de'][579] = {name = "Roter Wolf", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren roten Wolf oder gibt ihn wieder frei.\n[q]\"Es verbleiben nur noch wenige in ganz Azeroth, und nur die Erfahrensten von uns haben sie je zu Gesicht bekommen.\"\nKlassisch"}
MultiLanguageSpellData['de'][580] = {name = "Waldwolf", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren Waldwolf oder gibt ihn wieder frei.\n[q]\"Heult laut genug, um meilenweit gehört zu werden.\"\nVerkäufer:\nOgunaro Wolfsläufer\nZone:\nOrgrimmar\nKosten:\n1"}
MultiLanguageSpellData['de'][581] = {name = "Winterwolf", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren Winterwolf oder gibt ihn wieder frei.\n[q]\"Uralte Legenden der Furbolgs nach waren Wölfe mit weißem Fell durch die zwei Monde von Azeroth gesegnet.\"\nKlassisch"}
MultiLanguageSpellData['de'][585] = {name = "Heilige Pein", additional_info = "{3% von Grundmana} {40 Meter Reichweite}\nWirken in 1.5 sek.\n[q]Peinigt einen Gegner mit (70.5% of Spell power) Heiligschaden [ Refugium : und absorbiert die nächsten [(Spell power * 100 / 100) * (1 + Versatility)] Schaden, die von diesem Gegner verursacht werden ] [ Heiliges Feuer : Außerdem besteht eine Chance von 20%, die Abklingzeit von 'Heiliges Feuer' abzuschließen ]."}
MultiLanguageSpellData['de'][586] = {name = "Verblassen", additional_info = "{Sofort} {30 sek. Abklingzeit}\n[q]Lässt Euch verblassen und entfernt Eure gesamte Bedrohung. Verringert zusätzlich die Entfernung, aus der Gegner Euch angreifen. Hält 10 Sek. lang an."}
MultiLanguageSpellData['de'][589] = {name = "Schattenwort: Schmerz", additional_info = "{2% von Grundmana} {40 Meter Reichweite}\nSofort\n[q]Disziplin, Heilig\n Ein Wort der Dunkelheit, das sofort (12.92% of Spell power) Schattenschaden sowie im Verlauf von 16 Sek. zusätzlich (76.704% of Spell power) Schattenschaden verursacht.\n\nSchatten\n Ein Wort der Dunkelheit, das sofort (12.92% of Spell power) Schattenschaden sowie im Verlauf von 16 Sek. zusätzlich (76.704% of Spell power) Schattenschaden verursacht.\n\nErzeugt 3 Wahnsinn."}
MultiLanguageSpellData['de'][596] = {name = "Gebet der Heilung", additional_info = "{5% von Grundmana} {40 Meter Reichweite}\nWirken in 2.5 sek.\n[q]Ein mächtiges Gebet, das das Ziel und die 4 am nächsten stehenden Verbündeten innerhalb von 40 Metern um (320.953% of Spell power) Gesundheit heilt."}
MultiLanguageSpellData['de'][603] = {name = "Verdammnis", additional_info = "{1% von Grundmana} {40 Meter Reichweite}\n{Sofort} {30 sek. Abklingzeit}\n[q]Belegt das Ziel mit drohender Verdammnis, was sofort (104.406% of Spell power) Schattenschaden verursacht und nach 20 Sek. Gegnern innerhalb von 10 Metern (290.928% of Spell power) Schattenschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\n Das verzehren eines 'Dämonischen Kerns' verringert die Dauer von 'Verdammnis' um 3 Sek."}
MultiLanguageSpellData['de'][605] = {name = "Gedankenkontrolle", additional_info = "{2% von Grundmana} {30 Meter Reichweite}\nWirken in 1.8 sek."}
MultiLanguageSpellData['de'][606] = {name = "Gedankenverfall", additional_info = "{240 Mana} {30 Meter Reichweite}\nWirken in 2 sek.\n[q]Entzieht dem Ziel 30 Sek. lang insgesamt 34 Mana."}
MultiLanguageSpellData['de'][633] = {name = "Handauflegung", additional_info = "40 Meter Reichweite\nSofort 10 min Abklingzeit\n[q]Heilt ein verbündetes Ziel um einen Betrag, der 100% Eurer maximalen Gesundheit entspricht.\n\n Kann nicht auf Ziele gewirkt werden, die von 'Vorahnung' betroffen sind. Ruft den Effekt 'Vorahnung' hervor, der 30 Sek. lang anhält."}
MultiLanguageSpellData['de'][642] = {name = "Gottesschild", additional_info = "Sofort 5 min Abklingzeit\n[q]Gewährt 8 Sek. lang Immunität vor jeglichem Schaden, schädlichen Effekten, Rückstößen und erzwungenen Bewegungseffekten.\n\n Kann nicht eingesetzt werden, wenn 'Vorahnung' auf Euch wirkt. Ruft den Effekt 'Vorahnung' hervor, der 30 Sek. lang anhält."}
