MultiLanguageSpellData['de'][688] = {name = "Wichtel beschwören", additional_info = "1 Seelensplitter\nWirken in 6 sek.\n[q]Beschwört einen Wichtel, der unter Eurem Befehl steht und Feuerblitze verschießt."}
