MultiLanguageSpellData['de'][697] = {name = "Leerwandler beschwören", additional_info = "1 Seelensplitter\nWirken in 6 sek.\n[q]Beschwört einen Leerwandler, der unter Eurem Befehl steht und schwerem Schaden widerstehen kann."}
MultiLanguageSpellData['de'][698] = {name = "Ritual der Beschwörung", additional_info = "{5% von Grundmana} {30 Meter Reichweite}\nKanalisiert (Wirken in 2 min) 2 min Abklingzeit\n[q]Beginnt mit einem Ritual zur Erschaffung eines Beschwörungsportals, das vom Zaubernden und 2 Verbündeten abgeschlossen werden muss. Mithilfe des Portals können Gruppen- und Schlachtzugsmitglieder herbeigerufen werden."}
