MultiLanguageSpellData['de'][702] = {name = "Fluch der Schwäche", additional_info = "{1% von Grundmana} {40 Meter Reichweite}\nSofort\n[q]Erhöht die Zeit zwischen Angriffen eines Gegners 2 Min. lang um 20%.\n\nFlüche: Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein."}
MultiLanguageSpellData['de'][703] = {name = "Erdrosseln", additional_info = "{45 Energie} {Nahkampfreichweite}\n{Sofort} {6 sek. Abklingzeit}\nBenötigt Einhändige Nahkampfwaffe\n[q]Erdrosselt den Gegner und fügt ihm im Verlauf von 18 Sek. (311.4% of Attack power) Blutungsschaden zu.\n\nGewährt 1 Combopunkt."}
MultiLanguageSpellData['de'][710] = {name = "Verbannen", additional_info = "{1.5% von Grundmana} {30 Meter Reichweite}\nWirken in 1.5 sek.\n[q]Verbannt einen gegnerischen Dämon, eine Entartung [ Großes Verbannen : einen Untoten ] oder einen Elementar und macht das Ziel 30 Sek. lang handlungsunfähig. Maximal 1 Ziel. Wenn Ihr erneut 'Verbannen' auf das Ziel wirkt, wird der Effekt aufgehoben."}
MultiLanguageSpellData['de'][712] = {name = "Sukkubus beschwören", additional_info = "1 Seelensplitter\nWirken in 6 sek.\n[q]Beschwört einen Sukkubus, der unter Eurem Befehl steht und gegnerische Humanoide verführt, die dadurch nicht angreifen können."}
MultiLanguageSpellData['de'][720] = {name = "Umschlingen", additional_info = "Sofort\n[q]Die Brutstätte Fankriss' des Unnachgiebigen zieht das Ziel nahen Silithidjungtieren entgegen und macht es 8 Sek. lang bewegungsunfähig."}
