MultiLanguageSpellData['de'][759] = {name = "Manaedelstein herbeizaubern", additional_info = "18% von Grundmana\nWirken in 3 sek.\n[q]Zaubert einen Manaedelstein herbei, der zum sofortigen Wiederherstellen von 25% Mana verwendet werden kann und 12 Sek. lang 5% Zauberschaden gewährt. Enthält bis zu 3 Aufladungen.\n\nHerbeigezauberte Gegenstände\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Min. ausloggt."}
MultiLanguageSpellData['de'][768] = {name = "Katzengestalt", additional_info = "Sofort\n[q]Verwandelt Eure Gestalt in die einer Katze, erhöht den Schaden automatischer Angriffe um 40% sowie die Bewegungsgeschwindigkeit um 30%, schützt Euch vor Verwandlungseffekten und verringert den erlittenen Fallschaden.\n\n Der Akt des Gestaltwandelns befreit Euch von bewegungseinschränkenden Effekten."}
MultiLanguageSpellData['de'][772] = {name = "Verwunden", additional_info = "{20 Wut} {Nahkampfreichweite}\nSofort\nBenötigt Nahkampfwaffe\n[q]Verwundet das Ziel und fügt ihm sofort (124.581% of Attack power) körperlichen Schaden sowie zusätzlich im Verlauf von 15 Sek. (190.465% of Attack power) Blutungsschaden zu. [ Donnerknall : 'Donnerknall' belegt 5 Ziele in der Nähe mit 'Verwunden'. ]"}
MultiLanguageSpellData['de'][774] = {name = "Verjüngung", additional_info = "{5% von Grundmana} {40 Meter Reichweite}\nSofort\n[q]Heilt das Ziel im Verlauf von 12 Sek. um (103.52% of Spell power) Gesundheit. [ Verschmelzung : Ihr könnt 'Verjüngung' zweimal auf dasselbe Ziel anwenden ] [ Inkarnation: Baum des Lebens : Baum des Lebens: Heilung um 40% erhöht und Manakosten um 30% verringert. ]"}
MultiLanguageSpellData['de'][781] = {name = "Rückzug", additional_info = "Unbegrenzte Reichweite\n{Sofort} {20 sek. Abklingzeit}\n1 Aufladung\n[q]Springt rückwärts. [ Impromptu : Dabei befreit Ihr Euch von bewegungseinschränkenden Effekten und erhöht Eure Bewegungsgeschwindigkeit 4 Sek. lang um 0% ] [ Um ein Haar : Außerdem aktiviert Ihr eine Netzfalle, die alle gegnerischen Ziele innerhalb von 8 Metern mit klebrigen Netzen bedeckt, die sie 8 Sek. lang bewegungsunfähig machen ]"}
MultiLanguageSpellData['de'][783] = {name = "Reisegestalt", additional_info = "Sofort\n[q]Verwandelt Euch in eine an Eure aktuelle Umgebung angepasste Reisegestalt und erhöht Eure Bewegungsgeschwindigkeit auf Land, im Wasser oder in der Luft. Schützt Euch vor Verwandlungseffekten.\n\n Der Akt des Gestaltwandelns befreit Euch von bewegungseinschränkenden Effekten."}
MultiLanguageSpellData['de'][785] = {name = "Wahre Erfüllung", additional_info = "{260 Mana} {45 Meter Reichweite}\nWirken in 0.5 sek.\n[q]Von den Kräften des Propheten Skeram bekehrt, wird das Ziel mit heiliger Macht erfüllt. Die Zauber des Ziels werden sofort gewirkt, der verursachte Schaden ist um 300%, alle Widerstände sind um 269 und die Bewegungsgeschwindigkeit ist um 40% erhöht. Hält 20 Sek. lang an."}
