MultiLanguageSpellData['de'][974] = {name = "Erdschild", additional_info = "{5% von Grundmana} {40 Meter Reichweite}\nSofort Erfordert Level 30 (Elementar, Verstärkung)\n[q]Schützt das Ziel mit einem Erdschild, der Eure bei diesem Ziel hervorgerufene Heilung um 20% erhöht und es bei erlittenem Schaden um [(73% of Spell power) * (1.2)] Gesundheit heilt. Diese Heilung kann nur einmal alle 3 Sek. auftreten. Maximal 9 Aufladungen .\n\n [ Elementare Umkreisung : 'Erdschild' kann immer nur auf den Schamanen und ein weiteres Ziel gleichzeitig angewendet werden. Es können bis zu zwei Elementarschilde auf dem Schamanen aktiv sein / 'Erdschild' kann immer nur auf ein Ziel gleichzeitig angewendet werden. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.](3s Abklingzeit)"}
MultiLanguageSpellData['de'][980] = {name = "Agonie", additional_info = "{1% von Grundmana} {40 Meter Reichweite}\nSofort\n[q]Fügt dem Ziel immer stärkere Schmerzen zu, die im Verlauf von 18 Sek. [(3.01508% of Spell power) * 18 / 2 * 6] Schattenschaden verursachen. Zunächst wird nur geringer Schaden verursacht, der sich aber mit zunehmender Dauer erhöht. Durch die Auffrischung des Zaubers wird die aktuelle Schadensstufe beibehalten.\n\nWenn 'Agonie' Schaden verursacht, wird manchmal 1 Seelensplitter erzeugt."}
MultiLanguageSpellData['de'][982] = {name = "Tier wiederbeleben", additional_info = "35 Fokus\nWirken in 2.5 sek.\n[q]Bringt Euer totes Tier mit 100% seiner Grundgesundheit wieder ins Leben zurück."}
MultiLanguageSpellData['de'][1022] = {name = "Segen des Schutzes", additional_info = "{3% von Grundmana} {40 Meter Reichweite}\nSofort 5 min Abklingzeit\n1 Aufladung\n[q]Heilig, Vergeltung\n Segnet ein Gruppen- oder Schlachtzugsmitglied und gewährt ihm 10 Sek. lang Immunität gegen körperlichen Schaden und schädliche Effekte.\n\n Kann nicht auf Ziele gewirkt werden, die von 'Vorahnung' betroffen sind. Ruft den Effekt 'Vorahnung' hervor, der 30 Sek. lang anhält.\n\nSchutz\n Segnet ein Gruppen- oder Schlachtzugsmitglied und gewährt ihm 10 Sek. lang Immunität gegen körperlichen Schaden und schädliche Effekte.\n\n Kann nicht auf Ziele gewirkt werden, die von 'Vorahnung' betroffen sind. Ruft den Effekt 'Vorahnung' hervor, der 30 Sek. lang anhält.\n\n Teilt sich eine Abklingzeit mit 'Segen des Zauberschutzes'."}
MultiLanguageSpellData['de'][1044] = {name = "Segen der Freiheit", additional_info = "{1.4% von Grundmana} {40 Meter Reichweite}\n{Sofort} {25 sek. Abklingzeit}\n1 Aufladung\n[q]Segnet ein Gruppen- oder Schlachtzugsmitglied und gewährt ihm Immunität gegen bewegungseinschränkende Effekte. [ Absolute Freiheit : Zusätzlich erhöht der Segen seine Bewegungsgeschwindigkeit um 30% ]Hält 8 Sek. lang an."}
