MultiLanguageSpellData['de'][1064] = {name = "Kettenheilung", additional_info = "{15% von Grundmana} {40 Meter Reichweite}\nWirken in 2.5 sek.\n[q]Heilt das verbündete Ziel um (231% of Spell power) Gesundheit und springt dann bis zu 15 Meter auf die 3 am schwersten verletzten Verbündeten in der Nähe über, um sie zu heilen. Mit jedem Sprung verringert sich die Heilung um 30%."}
MultiLanguageSpellData['de'][1066] = {name = "Reisegestalt", additional_info = "Sofort\n[q]Verwandelt Euch in eine Wassergestalt. Die Schwimmgeschwindigkeit wird um 100% erhöht und Ihr könnt unter Wasser atmen. Beschützt Euch außerdem vor Verwandlungseffekten.\n\n Der Akt des Gestaltwandelns befreit Euch von bewegungseinschränkenden Effekten."}
MultiLanguageSpellData['de'][1079] = {name = "Zerfetzen", additional_info = "{20 Energie} {/ 1 zu 5 Combopunkte Nahkampfreichweite}\nSofort\nBenötigt Katzengestalt\n[q]Finishing-Move, der regelmäßigen Blutungsschaden verursacht. Hält pro Combopunkt länger an.\n\n 1 Punkt: [(64.44% of Attack power) * 2] im Verlauf von 8 Sek.\n 2 Punkte: [(64.44% of Attack power) * 3] im Verlauf von 12 Sek.\n 3 Punkte: [(64.44% of Attack power) * 4] im Verlauf von 16 Sek.\n 4 Punkte: [(64.44% of Attack power) * 5] im Verlauf von 20 Sek.\n 5 Punkte: [(64.44% of Attack power) * 6] im Verlauf von 24 Sek."}
MultiLanguageSpellData['de'][1090] = {name = "Schlaf", additional_info = "{90 Mana} {30 Meter Reichweite}\nWirken in 1.5 sek."}
