MultiLanguageSpellData['de'][1121] = {name = "Umschlingen", additional_info = "100 Meter Reichweite\nSofort\n[q]Die Brutstätte Fankriss' des Unnachgiebigen zieht das Ziel nahen Silithidjungtieren entgegen und macht es 8 Sek. lang bewegungsunfähig."}
MultiLanguageSpellData['de'][1122] = {name = "Höllenbestie beschwören", additional_info = "{2% von Grundmana} {30 Meter Reichweite}\nSofort 2 min Abklingzeit\n[q]Beschwört eine Höllenbestie aus dem Wirbelnden Nether, die beim Einschlag (60% of Spell power) Feuerschaden verursacht und alle Gegner im Effektbereich für 2 Sek. betäubt.\n\n Die Höllenbestie steht 30 Sek. lang unter Eurem Befehl, fügt allen Gegnern in der Nähe alle 2 Sek. [(55% of Spell power) * (111) / 100] Schaden zu und erzeugt alle 1 Sek. 1 Seelensplitterfragment."}
MultiLanguageSpellData['de'][1126] = {name = "Mal der Wildnis", additional_info = "{1% von Grundmana} {40 Meter Reichweite}\nSofort\n[q]Erfüllt ein verbündetes Ziel mit der Macht der Wildnis. Erhöht die Vielseitigkeit des Ziels 60 Min. lang um 3%.\n\n Wenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, erhalten alle Mitglieder den Effekt."}
