MultiLanguageSpellData['de'][1130] = {name = "Mal des Jägers", additional_info = "100 Meter Reichweite\nSofort\n[q]Belegt das Ziel mit dem Mal des Jägers, das den Distanzschaden aller Angreifer gegen dieses Ziel um 0% erhöht. Das Ziel kann immer vom Jäger gesehen und aufgespürt werden.\n\n Die Fähigkeiten 'Arkaner Schuss', 'Schimärenschuss', 'Tötungsbefehl' und 'Explosivschuss' rufen automatisch den Effekt von 'Mal des Jägers' hervor.\n\n Hält 5 Min. lang an."}
