MultiLanguageSpellData['de'][12902] = {name = "[q2]Gnomen-Net-o-Matik-Projektor", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr , Schattenseide (2), Dicke Spinnenseide (4), Robustes Sprengpulver (2), Mithrilbarren (4)\nBerufsausbilder:\nKlassische Ingenieurskunst (210)\nKosten:\n4\n60\n\n[q2]Gnomen-Net-o-Matik-Projektor\nWird beim Anlegen gebunden\nSchmuck\n[q2]Benutzen: Hält das Ziel 20 Sek. lang in einem Netz fest. Das Netz ist allerdings mit einer Menge Haken bestückt und verfängt sich manchmal auch in der Kleidung des Benutzers, wenn es abgefeuert wird... (10 Min Abklingzeit)\nBenötigtKlassische Ingenieurskunst\n(210)"}
MultiLanguageSpellData['de'][12903] = {name = "[q2]Gnomenunglücksverhinderungsgürtel", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchwärzlicher Gürtel , Mithrilbarren (4), Echtsilberbarren (2), Instabiler Auslöser , Aquamarin (2)\nOptionale Reagenzien:\n[] (#31)\nBerufsausbilder:\nKlassische Ingenieurskunst (215)\nKosten:\n5\n25\n\n[q2]Gnomenunglücksverhinderungsgürtel\nWird beim Anlegen gebunden\nTaille Leder\n3 Rüstung\n+3 Ausdauer\nHaltbarkeit 40 / 40\n[q2]Benutzen: Ein Kraftfeldschild schützt Euch 10 Min. lang vor bis zu 9 Schaden.\n WARNUNG: Kraftfeld kann überladen werden, wenn es getroffen wird. Der Träger wird dann für gewisse Zeit aus dieser Dimension entfernt. (Procchance: 5%) (1 Stunde Abklingzeit)\nBenötigtKlassische Ingenieurskunst\n(1)"}
MultiLanguageSpellData['de'][12905] = {name = "[q2]Gnomenraketenstiefel", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchwarze Magiestoffstiefel , Mithrilrohr (2), Schweres Leder (4), Robustes Sprengpulver (8), Gyrochronatom (4)\nBerufsausbilder:\nKlassische Ingenieurskunst (210)\nKosten:\n4\n60\n\n[q2]Gnomenraketenstiefel\nWird beim Anlegen gebunden\nFüße Stoff\n2 Rüstung\nHaltbarkeit 55 / 55\n[q2]Benutzen: Diese Stiefel erhöhen Eure Bewegungsgeschwindigkeit 20 Sek. lang erheblich. WARNUNG: Ihre Stromversorgung und Gyros funktionieren nicht immer so, wie sie eigentlich sollten. (15 Min Abklingzeit)\nBenötigtKlassische Ingenieurskunst\n(1)"}
