MultiLanguageSpellData['de'][22568] = {name = "Wilder Biss", additional_info = "{25 Energie} {/ 1 zu 5 Combopunkte Nahkampfreichweite}\nSofort\nBenötigt Katzengestalt\n[q]Finishing-Move, der pro Combopunkt körperlichen Schaden verursacht und bis zu 25 Energie zusätzlich verbraucht, um den Schaden um bis zu 100% zu erhöhen.\n\n 1 Punkt: [(138.3% of Attack power) * 1 / 5] Schaden\n 2 Punkte: [(138.3% of Attack power) * 2 / 5] Schaden\n 3 Punkte: [(138.3% of Attack power) * 3 / 5] Schaden\n 4 Punkte: [(138.3% of Attack power) * 4 / 5] Schaden\n 5 Punkte: [(138.3% of Attack power) * 5 / 5] Schaden"}
MultiLanguageSpellData['de'][22570] = {name = "Zerfleddern", additional_info = "{30 Energie} {/ 1 zu 5 Combopunkte Nahkampfreichweite}\n{Sofort} {20 sek. Abklingzeit}\nBenötigt Katzengestalt\n[q]Finishing-Move, der körperlichen Schaden verursacht und das Ziel betäubt. Schaden und Dauer erhöhen sich pro Combopunkt:\n\n 1 Punkt: [(16% of Attack power) * 1] Schaden, 1 Sek.\n 2 Punkte: [(16% of Attack power) * 2] Schaden, 2 Sek.\n 3 Punkte: [(16% of Attack power) * 3] Schaden, 3 Sek.\n 4 Punkte: [(16% of Attack power) * 4] Schaden, 4 Sek.\n 5 Punkte: [(16% of Attack power) * 5] Schaden, 5 Sek."}
