MultiLanguageSpellData['de'][23241] = {name = "Schneller blauer Raptor", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren schnellen blauen Raptor oder gibt ihn wieder frei.\n[q]\"Diese Dschungeljäger sind schon lange mit den Trollen verbündet und haben eine enge Bindung zu ihren Herren entwickelt. Sie sind zu Reittieren, Beschützern und Freunden geworden.\"\nVerkäufer:\nZjolnir\nZone:\nDurotar\nKosten:\n10"}
