MultiLanguageSpellData['de'][27585] = {name = "[q3]Schwerer Obsidiangürtel", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nKleiner Obsidiansplitter (14), Verzauberter Thoriumbarren (4), Essenz der Erde (2)\nVerkäufer:\nVargus\nZone:\nSilithus\nZirkel des Cenarius - Freundlich\nKosten:\n5\n\n[q3]Schwerer Obsidiangürtel\nWird beim Anlegen gebunden\nTaille Platte\n8 Rüstung\n+4 [Stärke oder Intelligenz]Haltbarkeit 50 / 50\n25"}
MultiLanguageSpellData['de'][27586] = {name = "[q4]Gezackter Obsidianschild", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nGroßer Obsidiansplitter (8), Kleiner Obsidiansplitter (24), Verzauberter Thoriumbarren (8), Essenz der Erde (4)\nVerkäufer:\nGeneralleutnant Andorov\nZone:\nSilithus\nZone:\nRuinen von Ahn'Qiraj\nZirkel des Cenarius - Respektvoll\nKosten:\n5\n\n[q4]Gezackter Obsidianschild\nWird beim Anlegen gebunden\nSchildhand Schild\n42 Rüstung\n+2 Stärke\n+6 Intelligenz\n+3 Ausdauer\n[q2]+ 2 Ausweichen\nHaltbarkeit 120 / 120\n[q2]Anlegen: Bei einem Treffer durch einen gegnerischen Zauber besteht eine Chance von 5%, dass der Angreifer 3 Sek. zum Schweigen gebracht wird. (Procchance: 5%, 20s Abklingzeit)\n25"}
MultiLanguageSpellData['de'][27587] = {name = "[q4]Dicke Obsidianbrustplatte", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nGroßer Obsidiansplitter (18), Kleiner Obsidiansplitter (40), Verzauberter Thoriumbarren (12), Essenz der Erde (10), Gewaltiger Smaragd (4)\nBeute von:\nDer Prophet Skeram\nZone:\nAhn'Qiraj\n\n[q4]Dicke Obsidianbrustplatte\nWird beim Anlegen gebunden\nBrust Platte\n14 Rüstung\n+5 [Stärke oder Intelligenz]+5 Ausdauer\nHaltbarkeit 165 / 165\n[q2]Anlegen: Bei einem Treffer durch einen Schadenszauber, der unregelmäßigen Schaden zufügt, besteht eine Chance von 30%, 6 Sek. lang einen Zauberschild zu aktivieren, der 179 Schaden der entsprechenden Schadenskategorie absorbiert. (Procchance: 30%, 10s Abklingzeit)\n25"}
MultiLanguageSpellData['de'][27588] = {name = "[q3]Leichter Obsidiangürtel", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nKleiner Obsidiansplitter (14), Verzaubertes Leder (4)\nVerkäufer:\nVargus\nZone:\nSilithus\nZirkel des Cenarius - Wohlwollend\nKosten:\n5\n\n[q3]Leichter Obsidiangürtel\nWird beim Anlegen gebunden\nTaille Kette\n5 Rüstung\n+3 [Beweglichkeit oder Intelligenz][q2]Erhöht Eure kritische Trefferwertung um + 4.\nHaltbarkeit 50 / 50\n25"}
MultiLanguageSpellData['de'][27589] = {name = "[q4]Dunkler Griff des Zerstörers", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nGroßer Obsidiansplitter (8), Kleiner Obsidiansplitter (24), Verzaubertes Leder (8), Fläschchen der obersten Macht\nBeute von:\nMoam\nZone:\nRuinen von Ahn'Qiraj\n\n[q4]Dunkler Griff des Zerstörers\nWird beim Anlegen gebunden\nHände Kette\n5 Rüstung\n+2 [Beweglichkeit oder Intelligenz][q2]Erhöht Eure kritische Trefferwertung um + 3.\nHaltbarkeit 55 / 55\n[q2]Anlegen: Bei einem erfolgreichen Nahkampf- oder Distanzangriff erhaltet Ihr 1 Mana, während dem Ziel 1 Mana entzogen werden.\n25"}
