MultiLanguageSpellData['de'][30566] = {name = "[q4]Verstärkter Helm des Vorarbeiters", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärteter Adamantitbarren (8), Urerde (12), Urfeuer (12)\nOptionale Reagenzien:\n[] (#47)\nBerufsausbilder:\nIngenieurskunst der Scherbenwelt (75)\nKosten:\n3\n50\n\n[q4]Verstärkter Helm des Vorarbeiters\nWird beim Aufheben gebunden\nKopf Kette\n7 Rüstung\n+3 [Beweglichkeit oder Intelligenz]+7 Ausdauer\nHaltbarkeit 100 / 100\n[q2]Anlegen: Erhöht Eure Chance, Betäubungs- und Desorientierungseffekten zu widerstehen, um 10%.\n24\nBenötigtIngenieurskunst der Scherbenwelt\n(1)"}
MultiLanguageSpellData['de'][30567] = {name = "Qual des Worgen", additional_info = "Sofort\n[q]Bricht das Siegel des Buches und gewährt Euch eine Chance, bei Nahkampf- und Distanzangriffen zusätzlichen Schattenschaden zu verursachen."}
MultiLanguageSpellData['de'][30568] = {name = "Gnomisches Flammengeschütz", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nAdamantitrahmen , Eine Handvoll Teufelseisenbolzen (2), Elementarsprengpulver (3), Teufelseisengehäuse\nBerufsausbilder:\nIngenieurskunst der Scherbenwelt (25)\nKosten:\n1\n\n(3)\n[q2]Benutzen: Errichtet schnell ein gnomisches Flammengeschütz zu Euren Füßen, das automatisch angreifen wird. Meistens Gegner. Das Geschütz fällt nach 45 Sek. in sich zusammen. (1 Min Abklingzeit)\n24\nBenötigtIngenieurskunst der Scherbenwelt\n(25)"}
MultiLanguageSpellData['de'][30569] = {name = "[q3]Gnomischer Geflügelisierer", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärtetes Adamantitrohr (2), Khoriumkraftkern (2), Arkaner Staub (10), Großer Prismasplitter (2)\nOptionale Reagenzien:\n[] (#31)\nBerufsausbilder:\nIngenieurskunst der Scherbenwelt (40)\nKosten:\n1\n50\n\n[q3]Gnomischer Geflügelisierer\nWird beim Anlegen gebunden\nSchmuck\n+8 Ausdauer\n[q2]Benutzen: Verwandelt den Gegner 15 Sek. lang in ein Huhn. Das heißt, falls die Transmogrifikationspolarität nicht verwechselt wurde... (5 Min Abklingzeit)\n24\nBenötigtIngenieurskunst der Scherbenwelt\n(40)\nBenötigtGnomeningenieur"}
MultiLanguageSpellData['de'][30570] = {name = "[q3]Gürtel der fast perfekten Unverwundbarkeit", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchweres Knotenhautleder (8), Khoriumkraftkern (4), Urleben (10), Urschatten (10), Empfindlicher Arkanitwandler (2)\nOptionale Reagenzien:\n[] (#31)\nBerufsausbilder:\nIngenieurskunst der Scherbenwelt (50)\nKosten:\n2\n\n[q3]Gürtel der fast perfekten Unverwundbarkeit\nWird beim Anlegen gebunden\nTaille Stoff\n2 Rüstung\n+2 Ausdauer\n[q2]+ 7 Vielseitigkeit\nHaltbarkeit 50 / 50\n[q2]Benutzen: Schützt Euch mit einem Energieschild, der 8 Sek. lang 217 Schaden aufhält. (5 Min Abklingzeit)\n24\nBenötigtIngenieurskunst der Scherbenwelt\n(1)\n[q]\"Der Schutz ist nicht immer wirksam. In SELTENEN Fällen kann der Träger zusätzlichen Schaden erleiden.\""}
