MultiLanguageSpellData['de'][31850] = {name = "Unermüdlicher Verteidiger", additional_info = "Sofort 2 min Abklingzeit\n[q]Verringert Euren sämtlichen erlittenen Schaden 8 Sek. lang um 20%.\n\n Während 'Unermüdlicher Verteidiger' aktiv ist, wird der nächste Angriff, der Euch normalerweise töten würde, Eure Gesundheit stattdessen auf 20% des maximalen Werts setzen."}
