MultiLanguageSpellData['de'][32182] = {name = "Heldentum", additional_info = "0.4% von Grundmana\nSofort 5 min Abklingzeit\n[q]Erhöht für 40 Sek. das Tempo aller Gruppen- und Schlachtzugsmitglieder um 30%.\n\n Verbündete, die diesen Effekt erhalten, werden erschöpft und können 10 Min. lang nicht mehr von 'Heldentum' oder 'Zeitkrümmung' profitieren."}
