MultiLanguageSpellData['de'][32193] = {name = "Blitzschlagwolke", additional_info = "30 Meter Reichweite\nSofort\n[q]Lässt eine Blitzschlagwolke entstehen, die 15 Sek. anhält und allen Feinden im ausgewählten Gebiet 4233 Naturschaden und alle 5 Sek. 1489 zusätzlichen Schaden zufügt."}
