MultiLanguageSpellData['de'][32235] = {name = "Goldener Greif", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren goldenen Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"In Sturmwind sind sie verrückt nach Löwen, und der Greif ist zur Hälfte ein Löwe. Das muss natürlich nicht heißen, dass ihnen beide Hälften zusagen. - Greifenmeister Krallenaxt\"\nVerkäufer:\nTannec Steinschnabel\nZone:\nSturmwind\nKosten:\n50"}
MultiLanguageSpellData['de'][32239] = {name = "Schwarzer Greif", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren schwarzen Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"In Sturmwind sind sie verrückt nach Löwen, und der Greif ist zur Hälfte ein Löwe. Das muss natürlich nicht heißen, dass ihnen beide Hälften zusagen. - Greifenmeister Krallenaxt\"\nVerkäufer:\nTannec Steinschnabel\nZone:\nSturmwind\nKosten:\n50"}
MultiLanguageSpellData['de'][32240] = {name = "Weißer Greif", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren weißen Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"In Sturmwind sind sie verrückt nach Löwen, und der Greif ist zur Hälfte ein Löwe. Das muss natürlich nicht heißen, dass ihnen beide Hälften zusagen. - Greifenmeister Krallenaxt\"\nVerkäufer:\nTannec Steinschnabel\nZone:\nSturmwind\nKosten:\n50"}
MultiLanguageSpellData['de'][32241] = {name = "Furcht", additional_info = "30 Meter Reichweite\nSofort\n[q]Versetzt einen Gegner in Angst und Schrecken, woraufhin er 6 Sek. lang verängstigt flieht. Es kann immer nur jeweils ein einzelnes Ziel in Angst und Schrecken versetzt werden."}
MultiLanguageSpellData['de'][32242] = {name = "Schneller blauer Greif", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren schnellen blauen Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"Die Horde hatte Drachen und wir hatten Greifen. Diesen Krieg haben wir gewonnen. - Ilsa Trubelbräu\"\nVerkäufer:\nTannec Steinschnabel\nZone:\nSturmwind\nKosten:\n50"}
MultiLanguageSpellData['de'][32243] = {name = "Lohfarbener Windreiter", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren lohfarbenen Windreiter oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"Seit sie von Cairne und Thrall aus den Klauen der bösartigen Harpyien befreit wurden, wurden viele dieser Wesen zu wertvollen Gefährten der Horde.\"\nVerkäufer:\nDrakma\nZone:\nOrgrimmar\nKosten:\n50"}
MultiLanguageSpellData['de'][32244] = {name = "Blauer Windreiter", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren blauen Windreiter oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"Seit sie von Cairne und Thrall aus den Klauen der bösartigen Harpyien befreit wurden, wurden viele dieser Wesen zu wertvollen Gefährten der Horde.\"\nVerkäufer:\nDrakma\nZone:\nOrgrimmar\nKosten:\n50"}
MultiLanguageSpellData['de'][32245] = {name = "Grüner Windreiter", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren grünen Windreiter oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"Seit sie von Cairne und Thrall aus den Klauen der bösartigen Harpyien befreit wurden, wurden viele dieser Wesen zu wertvollen Gefährten der Horde.\"\nVerkäufer:\nDrakma\nZone:\nOrgrimmar\nKosten:\n50"}
MultiLanguageSpellData['de'][32246] = {name = "Schneller roter Windreiter", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren schnellen roten Windreiter oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"Ich werde nie verstehen, warum sie schneller fliegen, wenn man sie in Rüstung kleidet. - Drakma\"\nVerkäufer:\nDrakma\nZone:\nOrgrimmar\nKosten:\n100"}
