MultiLanguageSpellData['de'][41607] = {name = "Stärkung von Shattrath", additional_info = "Sofort\n[q]Erhöht die maximale Gesundheit des Spielers 1 Stunde lang um 29 und das Ausweichen um 1 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an."}
MultiLanguageSpellData['de'][41608] = {name = "Unerbittlicher Angriff von Shattrath", additional_info = "Sofort\n[q]Erhöht die Angriffskraft 1 Stunde lang um 19 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\n Wirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau."}
MultiLanguageSpellData['de'][41609] = {name = "Stärkung von Shattrath", additional_info = "Sofort\n[q]Erhöht 1 Stunde lang die maximale Gesundheit um 500 und das Ausweichen um 10. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\n Wirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau."}
MultiLanguageSpellData['de'][41610] = {name = "Mächtige Wiederherstellung von Shattrath", additional_info = "Sofort\n[q]Erhöht die Vielseitigkeit 1 Stunde lang um 20 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\n Wirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und auf dem Sonnenbrunnenplateau."}
