MultiLanguageSpellData['de'][47534] = {name = "Vor Angst erstarren", additional_info = "20 Meter Reichweite\nWirken in 1 sek.\n[q]Versetzt einen Gegner in Angst und Schrecken, woraufhin er 2 Sek. lang verängstigt erstarrt. Es kann immer nur jeweils ein einzelnes Ziel in Angst und Schrecken versetzt werden."}
MultiLanguageSpellData['de'][47536] = {name = "Euphorie", additional_info = "{3.1% von Grundmana} {40 Meter Reichweite}\nSofort 1.5 min Abklingzeit\n[q]Wendet sofort 'Machtwort: Schild' auf Euer Ziel an. Eure nächsten 3 Einsätze von 'Machtwort: Schild' haben keine Abklingzeit und absorbieren 80% mehr Schaden."}
MultiLanguageSpellData['de'][47540] = {name = "Sühne", additional_info = "{1.6% von Grundmana} {40 Meter Reichweite}\nKanalisiert 9 sek. Abklingzeit\n[q]Feuert eine Salve heiligen Lichts auf das Ziel, die im Verlauf von 2 Sek. einem Gegner [(67.575% of Spell power) * 1 * 1 * (3 + 0 + 0 )] Heiligschaden zufügt oder einen Verbündeten um [(290.7% of Spell power) * 1 * (3 + 0 + 0 )] Gesundheit heilt. Kann aus der Bewegung heraus gewirkt werden.\n\n Wenn Ihr durch 'Sühne' Heilung hervorruft, werden alle Ziele, bei denen Eure 'Abbitte' aktiv ist, um (18.72% of Spell power) Gesundheit geheilt."}
