MultiLanguageSpellData['de'][53376] = {name = "Geweihter Zorn", additional_info = "[q]Heilig\n 'Zornige Vergeltung' und 'Kreuzzug der Vergeltung' verringern die Abklingzeit von 'Heiliger Schock' um 50% und die Dauer wird um 25% erhöht.\n\nSchutz\n Die Dauer von 'Zornige Vergeltung' ist um 25% erhöht. 'Zornige Vergeltung' und 'Schildwache' lassen 'Richturteil' zusätzlich 1 Heilige Kraft erzeugen"}
MultiLanguageSpellData['de'][53385] = {name = "Göttlicher Sturm", additional_info = "3 Heilige Kraft\nSofort\n[q]Entfesselt einen Wirbel göttlicher Energie, der allen Gegnern in der Nähe [ Brennender Kreuzzug : [(116.409% of Attack power) * 1.05] Strahlenschaden / (116.409% of Attack power) Heiligschaden] zufügt.\n\n Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu."}
MultiLanguageSpellData['de'][53389] = {name = "GPS (Großdrachen-Positionierungs-System)", additional_info = "Sofort\n[q]Befragt Euren Drachen über den nächsten Schritt in der Wiedereroberung des Oculus."}
MultiLanguageSpellData['de'][53390] = {name = "Flutwellen", additional_info = "Sofort\n[q]Der Einsatz von 'Springflut' gewährt 2 Stapel von 'Flutwellen'. 'Flutwellen' verringert die Zauberzeit Eurer nächsten 'Welle der Heilung' oder 'Kettenheilung' um 20% oder erhöht die Chance auf einen kritischen Effekt mit Eurer nächsten 'Heilende Woge' um 30%."}
