MultiLanguageSpellData['de'][53549] = {name = "Eisige Berührung", additional_info = "20 Meter Reichweite\nSofort\n[q]Verursacht 1 bis 1 Frostschaden (modifiziert durch Angriffskraft) und verringert bis Abbruch lang das Nahkampfangriffs-, Distanzangriffs- und Zaubertempo des Ziels um 1%."}
MultiLanguageSpellData['de'][53550] = {name = "Gedankenfrost", additional_info = "Nahkampfreichweite\nSofort\n[q]Die Gedanken des Ziels werden von einer Kälte geschlagen, die 1 Frostschaden verursacht (modifiziert durch Angriffskraft). Das Wirken von Zaubern wird unterbrochen sowie 4 Sek. lang verhindert, dass Zauber dieser Art gewirkt werden können."}
MultiLanguageSpellData['de'][53563] = {name = "Flamme des Glaubens", additional_info = "{0.5% von Grundmana} {60 Meter Reichweite}\nSofort\n[q]Hüllt einen einzelnen Verbündeten in heilige Energie, durch die Eure auf andere Gruppen- oder Schlachtzugsmitglieder gewirkten Heilungen dieses Ziel zusätzlich in Höhe von 10% des geheilten Werts heilen."}
MultiLanguageSpellData['de'][53570] = {name = "Zehrende Kälte", additional_info = "10 Meter Reichweite\nSofort\n[q]Entfesselt alle verfügbare Runenmacht, um der Erde unter dem Todesritter jegliche Wärme zu entziehen. Feinde innerhalb von 10 Metern werden in Eis eingeschlossen, das für 1 Sek. pro 5 Runenmacht jegliche ihrer Aktionen verhindert. Feinde zählen als eingefroren, jeglicher verursachte Schaden unterbricht den Effekt."}
MultiLanguageSpellData['de'][53576] = {name = "Lichtinfusion", additional_info = "[q]Kritische Effekte Eures Zaubers 'Heiliger Schock' ermächtigen Euren nächsten gewirkten Zauber:\n\nLichtblitz : Heilung um 30% erhöht.\nHeiliges Licht : Heilung um 30% erhöht.\nRichturteil : 'Großes Richturteil' verhindert zusätzlich 100% des Schadens, den das Ziel verursacht."}
MultiLanguageSpellData['de'][53595] = {name = "Hammer der Rechtschaffenen", additional_info = "{0.32% von Grundmana} {Nahkampfreichweite}\nSofort 5 sek. Wiederaufladung\n2 Aufladungen\n[q]Lässt einen Hammer auf das aktuelle Ziel niedergehen, der ihm (97.5% of Attack power)% körperlichen Schaden zufügt. [ Weihe : 'Hammer der Rechtschaffenen' ruft zusätzlich eine Lichtwelle hervor, die allen anderen Zielen innerhalb von 8 Metern (13.56% of Attack power)% Heiligschaden zufügt ] [ Während Ihr Euch im Effektbereich Eurer 'Weihe' aufhaltet, löst 'Hammer der Rechtschaffenen' zudem eine Lichtwelle aus, die allen anderen Zielen innerhalb von 8 Metern (13.56% of Attack power)% Heiligschaden zufügt ]\nErzeugt 1 Heilige Kraft."}
MultiLanguageSpellData['de'][53599] = {name = "Ungeziefer der Anub'ar beschwören", additional_info = nil}
MultiLanguageSpellData['de'][53600] = {name = "Schild der Rechtschaffenen", additional_info = "3 Heilige Kraft Nahkampfreichweite\n{Sofort} {1 sek. Abklingzeit}\n[q]Heilig\n Verpasst Gegnern vor Euch einen heftigen Schlag mit Eurem Schild, der (51% of Attack power) Heiligschaden verursacht und Eure Rüstung für 4.5 Sek. um (160 * $INT / 100) erhöht.\n\nVergeltung\n Verpasst Gegnern vor Euch einen heftigen Schlag mit Eurem Schild, der (51% of Attack power) Heiligschaden verursacht und Eure Rüstung für 4.5 Sek. um (160 * Strength / 100) erhöht.\n\nSchutz\n Verpasst Gegnern vor Euch einen heftigen Schlag mit Eurem Schild, der (51% of Attack power) Heiligschaden verursacht und Eure Rüstung für 4.5 Sek. um (160 * Strength / 100) erhöht.\n\nSchutz\n[q]Shield of the Righteous increases your Strength and Stamina by 2% for 10 sec, stacking up to 3."}
