MultiLanguageSpellData['de'][55976] = {name = "Zauberabwehr", additional_info = "Wirken in 1 sek.\n[q]Greift in der Nähe befindliche Feinde mit einem Wirbel von Stahl an, der 6 Sek. lang anhält und alle 2 Sek. Waffenschaden verursacht. Verleiht dem Zaubernden zeitweilige Magie-Immunität."}
