MultiLanguageSpellData['de'][56465] = {name = "[q3]Mechanische Schneebrille", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nSaronitbarren (8), Boreanisches Leder (2), Äonenschatten\nOptionale Reagenzien:\n[] (#47)\nBerufsausbilder:\nIngenieurskunst von Nordend (45)\nKosten:\n1\n75\n\n[q3]Mechanische Schneebrille\nWird beim Anlegen gebunden\nKopf Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nHaltbarkeit 85 / 85\n[q2]Anlegen: Vor Kälte geschützt. Euer Frostwiderstand ist um 6 erhöht.\n24\nBenötigtIngenieurskunst von Nordend\n(1)"}
MultiLanguageSpellData['de'][56466] = {name = "[q3]Überschallbooster", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nFroststahlröhre (2), Überladener Kondensator (4), Eine Handvoll Kobaltbolzen (2)\nOptionale Reagenzien:\n[] (#31)\nBerufsausbilder:\nIngenieurskunst von Nordend (45)\nKosten:\n1\n75\n\n[q3]Überschallbooster\nWird beim Anlegen gebunden\nSchmuck\n+5 Ausdauer\n[q2]Anlegen: In manchen Fällen schärft der Lärm von Nahkämpfen Euer Schallbewusstsein und erhöht 10 Sek. lang Eure Angriffskraft um 14 . Dieser Effekt kann pro Minute nur einmal auftreten. (Procchance: 35%, 50s Abklingzeit)\n24\nBenötigtIngenieurskunst von Nordend\n(15)"}
MultiLanguageSpellData['de'][56467] = {name = "[q3]Lärmmaschine", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nFroststahlröhre (2), Überladener Kondensator (2), Eine Handvoll Kobaltbolzen (8)\nOptionale Reagenzien:\n[] (#31)\nBerufsausbilder:\nIngenieurskunst von Nordend (45)\nKosten:\n1\n75\n\n[q3]Lärmmaschine\nWird beim Anlegen gebunden\nSchmuck\n+4 Intelligenz\n[q2]Anlegen: Nahkampfangriffe auf Euch haben eine Chance, einen Schallschild zu beschwören, der 6 Schaden absorbiert. Dieser Effekt kann nur einmal pro Minute auftreten. (Procchance: 50%, 50s Abklingzeit)\n24\nBenötigtIngenieurskunst von Nordend\n(15)"}
