MultiLanguageSpellData['de'][59567] = {name = "Azurblauer Drache", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren azurblauen Drachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n[q]\"Bleibt besser höflich, wenn Ihr mit einem wütenden Drachen sprecht.\"\nBeute von:\nAlexstraszas Geschenk\nOrt:\nAuge der Ewigkeit"}
MultiLanguageSpellData['de'][59568] = {name = "Blaudrache", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren Blaudrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n[q]\"Stellt Euch nicht zwischen einen Drachen und seinen Zorn.\"\nBeute von:\nAlexstraszas Geschenk\nOrt:\nAuge der Ewigkeit"}
MultiLanguageSpellData['de'][59569] = {name = "Bronzedrache", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren Bronzedrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n[q]\"Verlorene Zeit kommt niemals zurück. Oh wartet, da ist sie ja. - Chronormu\"\nBeute von:\nEwiger Verderber\nZone:\nDas Ausmerzen von Stratholme"}
MultiLanguageSpellData['de'][59570] = {name = "Rotdrache", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren Rotdrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n[q]\"Ihr solltet nicht auf die Fantasien der Barden hören. Ein Drache würde keiner Fliege etwas zuleide tun, solange er nicht zuerst angegriffen wurde.\"\nVerkäufer:\nCielstrasza\nZone:\nDrachenöde\nDer Wyrmruhpakt - Ehrfürchtig\nKosten:\n2000"}
MultiLanguageSpellData['de'][59571] = {name = "Zwielichtdrache", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren Zwielichtdrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n[q]\"Aber die wichtigste Regel, die Regel, die Ihr niemals vergessen dürft, ist: Egal, wie viel er schreien mag, egal, wie sehr er bettelt, füttert ihn niemals nach Mitternacht.\"\nBeute von:\nSartharion\nOrt:\nDas Obsidiansanktum"}
