MultiLanguageSpellData['de'][60018] = {name = "Verwüsten", additional_info = "Nahkampfreichweite\nSofort\n[q]Zerreißt die Rüstung des Ziels und ruft den Effekt 'Rüstung zerreißen' hervor. Verursacht zusätzlich 50% Waffenschaden plus 90 pro Stapel dieses Effektes auf dem Ziel. 'Rüstung zerreißen' ist bis zu 5-mal stapelbar."}
MultiLanguageSpellData['de'][60019] = {name = "Donnerknall", additional_info = "{Sofort} {6 sek. Abklingzeit}\n[q]Trifft Gegner in der Nähe, erhöht die Zeit zwischen ihren Angriffen 30 Sek. lang um 20% und verursacht 6 Schaden. Schaden wird durch Angriffskraft erhöht. Diese Fähigkeit verursacht zusätzliche Bedrohung und wirkt auf maximal 4 Ziele."}
MultiLanguageSpellData['de'][60020] = {name = "Eiswolke", additional_info = "Sofort\n[q]Verursacht sofort 31 Frostschaden und danach pro Sek. 15 Frostschaden. Hält 10 Sek. lang an."}
MultiLanguageSpellData['de'][60021] = {name = "Verseuchter Protodrache", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren verseuchten Protodrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n[q]\"Gezüchtet, um jene Helden zu ehren, die Mut und Durchhaltevermögen gegen die Gefahren in Nordend bewiesen haben.\"\nKlassisch"}
