MultiLanguageSpellData['de'][60024] = {name = "Violetter Protodrache", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren violetten Protodrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n[q]\"Ich frage mich immer wieder, ob die Dinge sich nicht anders entwickelt hätten, wenn die Titanen auch nur einen weiteren Drachenschwarm erhoben hätten. - Alexstrasza\"\nErfolg:\nWas für eine lange, seltsame Reise...\nKategorie:\nWeltereignisse"}
MultiLanguageSpellData['de'][60025] = {name = "Albinodrache", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren Albinodrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n[q]\"Selbst die Versuche der Gesellschaft für einheimische Drachen haben keine klaren Erkenntnisse darüber gebracht, ob der Albinodrache mit einem der bekannten Drachenschwärme verwandt ist. - Breanni\"\nErfolg:\nFühren der Kavallerie\nKategorie:\nAllgemein"}
