MultiLanguageSpellData['de'][63556] = {name = "Pflege", additional_info = "{22% von Grundmana} {40 Meter Reichweite}\nWirken in 1.5 sek.\n[q]Heilt ein befreundetes Ziel um 0. Ist ein durch Euch gewirkter Effekt von 'Verjüngung', 'Nachwachsen' oder 'Blühendes Leben' auf dem Ziel aktiv, erhöht sich die Heilung um zusätzliche 20%."}
