MultiLanguageSpellData['de'][65790] = {name = "Gegenzauber", additional_info = "{9% von Grundmana} {30 Meter Reichweite}\n{Sofort} {24 sek. Abklingzeit}\n[q]Kontert das Zauberwirken des Feindes und verhindert 8 Sek. lang, dass ein Zauber dieser Art der Magie gewirkt werden kann. Führt zu einem hohen Maß an Bedrohung."}
MultiLanguageSpellData['de'][65791] = {name = "Arkanschlag", additional_info = "{8% von Grundmana} {30 Meter Reichweite}\nWirken in 2.5 sek.\n[q]Überzieht einen Feind mit Energie und verursacht 2266 Arkanschaden. Mit jedem Wirken von 'Arkanschlag' werden der verursachte Schaden aller Arkanzauber um 60% und die Manakosten von 'Arkanschlag' um 90% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar und hält bis Abbruch lang an oder bis ein Arkanzauber außer 'Arkanschlag' gewirkt wurde."}
MultiLanguageSpellData['de'][65792] = {name = "Frostnova", additional_info = "8% von Grundmana\n{Sofort} {25 sek. Abklingzeit}\n[q]Überzieht Gegner in der Nähe des Zaubernden mit Kälte, fügt ihnen (19.3% of Spell power) Frostschaden zu und friert sie bis zu 8 Sek. lang ein. Erlittener Schaden kann den Effekt unterbrechen."}
MultiLanguageSpellData['de'][65793] = {name = "Blinzeln", additional_info = "21% von Grundmana\n{Sofort} {15 sek. Abklingzeit}\n[q]Teleportiert den Zaubernden 20 Meter nach vorn, es sei denn, etwas steht im Weg. Befreit den Zaubernden auch von Betäubungen und Fesseln."}
