MultiLanguageSpellData['de'][65798] = {name = "Sternenregen", additional_info = "{Kanalisiert (Wirken in} {8 sek.) 30 sek. Abklingzeit}\n[q]Beschwört einen Wirbel aus Sternen vom Himmel auf alle Ziele im Umkreis von 30 Metern um den Zaubernden herab, von denen jeder allen Feinden im Umkreis von 5 Metern um das feindliche Ziel 55 Arkanschaden zufügt. Hält 8 Sek. lang an."}
MultiLanguageSpellData['de'][65799] = {name = "Arkanbeschuss", additional_info = "{18% von Grundmana} {30 Meter Reichweite}\n{Sofort} {3 sek. Abklingzeit}\n[q]Schleudert mehrere Geschosse auf das feindliche Ziel und verursacht 1846 Arkanschaden."}
MultiLanguageSpellData['de'][65800] = {name = "Arkane Explosion", additional_info = "22% von Grundmana\nSofort\n[q]Verursacht eine Explosion arkaner Magie um den Zaubernden herum und fügt allen Zielen in einem Umkreis von 10 Metern 24 Arkanschaden zu."}
MultiLanguageSpellData['de'][65801] = {name = "Verwandlung", additional_info = "{7% von Grundmana} {30 Meter Reichweite}\n{Wirken in} {1.5 sek. 15 sek. Abklingzeit}\n[q]Verwandelt den Feind in ein Schaf und zwingt ihn, 10 Sek. lang so herumzuwandern. Während das Schaf herumwandert, kann es weder angreifen noch Zauber wirken. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren."}
MultiLanguageSpellData['de'][65802] = {name = "Eisblock", additional_info = "15 Mana\nSofort 5 min Abklingzeit\n[q]Ihr werdet in einen Eisblock eingehüllt, der Euch 5 Sek. lang vor allen körperlichen Angriffen und Zaubern schützt, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen und auch keine Zauber wirken. Verursacht ebenfalls 'Unterkühlung' und verhindert 30 Sek. lang, dass 'Eisblock' gewirkt werden kann."}
