MultiLanguageSpellData['de'][75596] = {name = "Fliegender Frostteppich", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen fliegenden Frostteppich oder gibt ihn wieder frei. Dieses Fortbewegungsmittel passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"Ich kann mich noch an meinen ersten fliegenden Teppich erinnern... Yetihaar und Leinen. Keineswegs so angenehm wie dieser hier. - Frozo der Wohlbekannte\"\nBeruf:\nSchneidern"}
MultiLanguageSpellData['de'][75597] = {name = "[q4]Fliegender Frostteppich", additional_info = "Wirken in 3.5 sek.\nReagenzien:\nMondgespinst , Zaubertuch , Schwarztuch , Gefrorene Kugel (4)\nVerkäufer:\nFrozo der Wohlbekannte\nZone:\nKristallsangwald\nKosten:\n6\n\n[q4]Fliegender Frostteppich\nWird beim Aufheben gebunden\nReittier[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört einen fliegenden Frostteppich oder gibt ihn wieder frei. Dieses Fortbewegungsmittel passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n1 - 80 ( 80)\nBenötigtSchneiderei von Nordend\n(1)\nBenötigtUnerfahrenes Reiten\n\n\n[q]\"Ich kann mich noch an meinen ersten fliegenden Teppich erinnern... Yetihaar und Leinen. Keineswegs so angenehm wie dieser hier. - Frozo der Wohlbekannte\"\nBeruf:\nSchneidern"}
