MultiLanguageSpellData['de'][79954] = {name = "Teufelsrüstung", additional_info = "28% von Grundmana\nSofort\n[q]Umgibt Euch mit Teufelsenergie, die Eure Zaubermacht um 10% erhöht. Zusätzlich regeneriert Ihr alle 5 Sek. 2% Eurer gesamten Gesundheit. Es kann immer nur eine Art Rüstungszauber gleichzeitig aktiv sein. Hält 30 Min. lang an."}
