MultiLanguageSpellData['de'][79963] = {name = "Aura der Konzentration", additional_info = "Sofort\n[q]Verbündete im Umkreis von 40 Metern verlieren bei erlittenem Schaden 100% weniger Zauber- und Kanalisierungszeit."}
