MultiLanguageSpellData['de'][79965] = {name = "Schild des Rächers", additional_info = "{30 Mana} {30 Meter Reichweite}\nWirken in 1 sek.\n[q]Schleudert einen heiligen Schild auf den Gegner, der Heiligschaden zufügt, ihn benommen macht und dann auf weitere nahe Gegner überspringt. Wirkt auf insgesamt 2 Ziele."}
