MultiLanguageSpellData['de'][79967] = {name = "Heiliger Schild", additional_info = "10% von Grundmana\nSofort\n[q]Erhöht die Blockchance 10 Sek. lang um 30% und verursacht, während der Effekt aktiv ist, mit jedem Blocken Heiligschaden. Jedes Blocken zehrt eine Aufladung auf. 3 Aufladungen."}
