MultiLanguageSpellData['de'][79970] = {name = "Göttlicher Sturm", additional_info = "{20% von Grundmana} {Nahkampfreichweite}\nSofort\n[q]Ein sofortiger Waffenangriff, der bis zu 4 Gegnern innerhalb von 8 Metern Heiligschaden zufügt."}
