MultiLanguageSpellData['de'][80016] = {name = "Mal des Jägers", additional_info = "100 Meter Reichweite\nSofort\n[q]Belegt das Ziel mit dem Mal des Jägers. Erhöht die Distanzschaden aller Angreifer gegen dieses Ziel um 30%. Zudem kann das Ziel dieser Fähigkeit stets vom Jäger gesehen werden, auch wenn es in den Verstohlenheitsmodus geht oder unsichtbar wird. Das Ziel wird außerdem auf der Minikarte angezeigt. Hält 30 Sek. lang an."}
