MultiLanguageSpellData['de'][84411] = {name = "[q3]Hochleistungsbolzenschusspistole", additional_info = "Wirken in 3 sek.\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nObsidiumbarren (10), Eine Handvoll Obsidiumbolzen (8), Elektrifizierter Äther (4)\nBerufsausbilder:\nIngenieurskunst des Kataklysmus (15)\nKosten:\n50\n\n[q3]Hochleistungsbolzenschusspistole\nWird bei Benutzung gebunden\n[q2]Benutzen: Feuert einige geladene Bolzen auf einen Feind ab und verursacht so 108 Schaden, ebenso wird ein gewirkter Zauber kurzzeitig unterbrochen. Verbraucht mit jedem Schuss eine Handvoll Obsidiumbolzen. (2 Min Abklingzeit)\n29\nBenötigtIngenieurskunst des Kataklysmus\n(1)\n[q]\"Fast so schwer zu bedienen wie herzustellen.\""}
MultiLanguageSpellData['de'][84412] = {name = "[q2]Persönlicher Weltenzerstörer", additional_info = "Wirken in 3.5 sek.\nTools: Hochleistungsbolzenschusspistole , Schmiedehammer\nReagenzien:\nObsidiumbarren (10), Eine Handvoll Obsidiumbolzen (8), Elektrifizierter Äther (8)\nBerufsausbilder:\nIngenieurskunst des Kataklysmus (25)\nKosten:\n1\n\n[q2]Persönlicher Weltenzerstörer\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Euren persönlichen Weltenzerstörer beschwören oder wieder freigeben.\n1 - 80 ( 80)"}
